settings.custom_liquid:
{%- if section.index > 3 -%}
  <link rel="stylesheet" href="{{ 'c-prime-hp-09.css' | asset_url }}" media="print" onload="this.media='all'">
{%- else -%}
  {{ 'c-prime-hp-09.css' | asset_url | stylesheet_tag }}
{%- endif -%}
<div class="hero-wrap">

  <div class="hero-inner">

    <!-- LEFT: COPY -->
    <div class="hero-copy">

      <div class="hero-eyebrow">
        <span class="hero-eyebrow__dot"></span>
        Trusted by 18,000+ families worldwide
      </div>

      <h1 class="hero-title">
        Unlock Your Child's<br>
        <em>Full Potential</em><br>
        One "Why?" at a Time
      </h1>

      <p class="hero-sub">
        The encyclopedia that answers the questions curious kids actually ask — sparking deeper thinking, faster learning, and a genuine love of knowledge that lasts a lifetime.
      </p>

      <div class="hero-stars-row">
        <span class="hero-stars">★★★★★</span>
        <span class="hero-stars-label">4.9 · 2,847 verified reviews</span>
      </div>

      <div class="hero-price-row">
        <span class="hero-price">$39.90</span>
        <span class="hero-price-orig"><s>$79.80</s></span>
        <span class="hero-price-badge">50% OFF</span>
      </div>

      <a href="https://primenaturals.store/products/kidss-encyclopedia-10-000-whys" class="hero-btn">
        <span class="hero-btn__icon">🧠</span>
        Get The Encyclopedia
        <span class="hero-btn__arrow">→</span>
      </a>

      <div class="hero-trust">
        <span class="hero-trust__item">🛡️ 30-Day Guarantee</span>
        <span class="hero-trust__sep">·</span>
        <span class="hero-trust__item">📦 Free Shipping</span>
        <span class="hero-trust__sep">·</span>
        <span class="hero-trust__item">🔒 Secure Checkout</span>
      </div>

    </div>

    <!-- RIGHT: BOOK IMAGE -->
    <div class="hero-visual">

      <div class="hero-img-wrap">
        <img
          src="https://cdn.shopify.com/s/files/1/0610/1463/8726/files/1778076999755-cnt4qyxm57l-removebg.png?v=1778081453"
          alt="10,000 Whys — Children's Encyclopedia"
          class="hero-book-img"
          onerror="this.style.display='none'"
        />
      </div>

      <div class="hero-float hero-float--1">
        <span class="hero-float__icon">🧠</span>
        <span class="hero-float__text">Builds Cognitive Skills</span>
      </div>
      <div class="hero-float hero-float--2">
        <span class="hero-float__icon">⚡</span>
        <span class="hero-float__text">Learn Faster</span>
      </div>
      <div class="hero-float hero-float--3">
        <span class="hero-float__icon">📚</span>
        <span class="hero-float__text">Ages 6–12</span>
      </div>

    </div>

  </div>

</div>

<style>

  .hero-wrap *,
  .hero-wrap *::before,
  .hero-wrap *::after {
    box-sizing: border-box;
  }

  .hero-wrap {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background: #fffdf5;
    width: 100%;
    overflow: hidden;
  }

  .hero-inner {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 56px;
    align-items: center;
    max-width: 1100px;
    margin: 0 auto;
    padding: 72px 48px 80px;
  }

  .hero-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: #dcfce7;
    color: #166534;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    padding: 6px 14px;
    border-radius: 100px;
    margin-bottom: 22px;
    line-height: 1;
  }
  .hero-eyebrow__dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #166534;
    flex-shrink: 0;
  }

  .hero-title {
    font-size: clamp(32px, 4vw, 52px);
    font-weight: 900;
    line-height: 1.07;
    letter-spacing: -1.5px;
    color: #0d1b3e;
    margin: 0 0 22px 0;
  }
  .hero-title em {
    font-style: italic;
    color: #c0392b;
    font-weight: 400;
  }

  .hero-sub {
    font-size: clamp(14px, 1.5vw, 16px);
    line-height: 1.8;
    color: #6b7280;
    margin: 0 0 24px 0;
    max-width: 460px;
  }

  .hero-stars-row {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 22px;
    flex-wrap: wrap;
  }
  .hero-stars {
    color: #f59e0b;
    font-size: 16px;
    letter-spacing: 2px;
    line-height: 1;
  }
  .hero-stars-label {
    font-size: 13px;
    font-weight: 600;
    color: #6b7280;
  }

  .hero-price-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 30px;
    flex-wrap: wrap;
  }
  .hero-price {
    font-size: clamp(32px, 4vw, 44px);
    font-weight: 900;
    color: #c0392b;
    line-height: 1;
    letter-spacing: -1.5px;
  }
  .hero-price-orig s {
    font-size: 18px;
    color: #9ca3af;
    font-weight: 500;
    text-decoration-color: #9ca3af;
  }
  .hero-price-badge {
    background: #c0392b;
    color: #fff;
    border-radius: 6px;
    padding: 5px 11px;
    font-size: 12px;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    line-height: 1;
  }

  .hero-btn {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: #c0392b;
    color: #fff;
    text-decoration: none;
    padding: 17px 32px;
    border-radius: 10px;
    font-size: clamp(14px, 1.5vw, 16px);
    font-weight: 800;
    letter-spacing: 0.01em;
    margin-bottom: 24px;
    box-shadow:
      0 2px 6px rgba(192,57,43,0.25),
      0 8px 24px rgba(192,57,43,0.2);
    transition: background 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
    width: fit-content;
  }
  .hero-btn:hover {
    background: #a93226;
    transform: translateY(-2px);
    box-shadow:
      0 4px 10px rgba(192,57,43,0.3),
      0 14px 32px rgba(192,57,43,0.25);
  }
  .hero-btn__icon { font-size: 18px; line-height: 1; }
  .hero-btn__arrow {
    font-size: 18px;
    line-height: 1;
    transition: transform 0.2s ease;
  }
  .hero-btn:hover .hero-btn__arrow { transform: translateX(4px); }

  .hero-trust {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }
  .hero-trust__item {
    font-size: 12.5px;
    font-weight: 600;
    color: #9ca3af;
  }
  .hero-trust__sep {
    color: #e5e7eb;
    font-size: 12px;
  }

  .hero-visual {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 460px;
  }

  .hero-img-wrap {
    position: relative;
    z-index: 1;
    filter:
      drop-shadow(0 24px 48px rgba(13,27,62,0.2))
      drop-shadow(0 8px 16px rgba(13,27,62,0.12));
    transition: transform 0.4s ease, filter 0.4s ease;
  }
  .hero-img-wrap:hover {
    transform: rotate(-1deg) scale(1.03) translateY(-4px);
    filter:
      drop-shadow(0 32px 64px rgba(13,27,62,0.26))
      drop-shadow(0 12px 24px rgba(13,27,62,0.16));
  }
  .hero-book-img {
    width: 100%;
    max-width: 340px;
    height: auto;
    display: block;
  }

  .hero-float {
    position: absolute;
    background: #ffffff;
    border: 1px solid rgba(13,27,62,0.08);
    border-radius: 10px;
    padding: 10px 14px;
    display: flex;
    align-items: center;
    gap: 8px;
    box-shadow:
      0 2px 8px rgba(13,27,62,0.07),
      0 6px 20px rgba(13,27,62,0.07);
    white-space: nowrap;
    z-index: 2;
  }
  .hero-float__icon { font-size: 18px; line-height: 1; flex-shrink: 0; }
  .hero-float__text { font-size: 12.5px; font-weight: 700; color: #0d1b3e; }

  .hero-float--1 {
    top: 32px; right: 0;
    animation: heroFloat 3.5s ease-in-out infinite;
  }
  .hero-float--2 {
    bottom: 100px; left: 0;
    animation: heroFloat 3.5s 1.2s ease-in-out infinite;
  }
  .hero-float--3 {
    bottom: 32px; right: 16px;
    animation: heroFloat 3.5s 0.6s ease-in-out infinite;
  }

  @keyframes heroFloat {
    0%, 100% { transform: translateY(0); }
    50%       { transform: translateY(-8px); }
  }

  @media (max-width: 900px) {
    .hero-inner {
      grid-template-columns: 1fr;
      gap: 48px;
      padding: 48px 32px 64px;
      text-align: center;
    }
    .hero-copy {
      display: flex;
      flex-direction: column;
      align-items: center;
    }
    .hero-sub { margin: 0 auto 24px; }
    .hero-stars-row,
    .hero-price-row,
    .hero-trust { justify-content: center; }
    .hero-visual { min-height: 380px; }
    .hero-book-img { max-width: 300px; }
    .hero-float--2 { left: 10px; }
  }

  @media (max-width: 480px) {
    .hero-inner {
      padding: 36px 20px 52px;
      gap: 40px;
    }
    .hero-title { letter-spacing: -1px; }
    .hero-btn {
      width: 100%;
      justify-content: center;
      padding: 17px 20px;
    }
    .hero-book-img { max-width: 260px; }
    .hero-float { padding: 8px 12px; }
    .hero-float__text { font-size: 11.5px; }
    .hero-float--1 { top: 8px; right: -4px; }
    .hero-float--2 { bottom: 80px; left: -4px; }
    .hero-float--3 { bottom: 8px; right: 0; }
    .hero-trust__sep { display: none; }
    .hero-trust { gap: 6px; }
    .hero-trust__item { font-size: 12px; }
  }

</style>
